55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	
63	const BASE_PREMIUMS: Record<string, number> = {
64	  sword: 100,
65	  amulet: 60,
66	  staff: 80,
67	  potion: 40,
68	  rune: 25,
69	  moonstone: 25,
70	};
71	
72	const BLOCK_SIZE = 3;
73	const BLOCK_BASE_PREMIUM = 60;
74	
75	const countByType = (items: Item[]): Map<string, number> => {
76	  const counts = new Map<string, number>();
77	  for (const item of items) {
78	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
79	  }
80	  return counts;
81	};
82	
83	const basePremiumOfGroup = (type: string, count: number): number =>
84	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
85	
86	const policyBasePremium = (items: Item[]): number =>
87	  [...countByType(items)].reduce(
88	    (total, [type, count]) => total + basePremiumOfGroup(type, count),
89	    0,
90	  );
91	
92	const firstInsuranceSurcharge = (policyBase: number): number =>
93	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
94	
95	const surchargeWhen = (applies: boolean, item: Item, rate: number): number =>
96	  applies ? BASE_PREMIUMS[item.type] * rate : 0;
97	
98	const curseSurcharge = (item: Item): number =>
99	  surchargeWhen(item.cursed === true, item, CURSE_SURCHARGE_RATE);
100	
101	const highEnchantmentSurcharge = (item: Item): number =>
102	  surchargeWhen(
103	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
104	    item,
105	    HIGH_ENCHANTMENT_SURCHARGE_RATE,
106	  );
107	
108	const itemSurchargeTotal = (items: Item[]): number =>
109	  items.reduce(
110	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
111	    0,
112	  );
113	
114	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
115	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
116	    ? policyBase * LOYALTY_DISCOUNT_RATE
117	    : 0;
118	
119	const quote = (step: QuoteStep, customer: Customer): QuoteResult => {
120	  const policyBase = policyBasePremium(step.items);
121	  const premiumBeforeRounding =
122	    policyBase +
123	    itemSurchargeTotal(step.items) +
124	    firstInsuranceSurcharge(policyBase) -
125	    loyaltyDiscount(policyBase, customer) +
126	    PROCESSING_FEE;
127	  return { premium: Math.ceil(premiumBeforeRounding) };
128	};
129	
130	export const runScenario = (scenario: Scenario): ScenarioOutput => {
131	  return {
132	    results: scenario.steps.map((step) => quote(step as QuoteStep, scenario.customer)),
133	  };
134	};
